/**
 * NGO starter package (D6).
 *
 * Three deliberate constraints:
 * - We link to the vendors' official download pages and never host or mirror
 *   installers. Redistribution, update hygiene and integrity would otherwise be
 *   ours to carry, for zero benefit to the NGO.
 * - We ship no checksums here. A stale or wrong checksum is worse than none;
 *   every vendor publishes current ones next to the download.
 * - The device guide names no refurbishing partners (founder decision).
 *
 * Every template exists in German and English. The ODF files are generated by
 * `tools/build_ngo_starter.py` into `public/ngo-starter/`; regenerate rather
 * than hand-editing them.
 */

export type StarterLocale = "de" | "en";

export type StarterTemplate = {
  key: string;
  title: string;
  description: string;
  format: "ODT" | "ODS";
  files: Record<StarterLocale, string>;
};

export type StarterSoftware = {
  name: string;
  purpose: string;
  href: string;
  platforms: string;
};

export const STARTER_BUNDLES: Record<StarterLocale, string> = {
  de: "/ngo-starter/ngo-starter-paket.zip",
  en: "/ngo-starter/ngo-starter-package-en.zip"
};

